static const lv_image_dsc_t *AtlasIconAsset(kshim_menu_role_t Role)
{
  switch (Role) {
  case KSHIM_MENU_ROLE_BASE: case KSHIM_MENU_ROLE_ANDROID: return &AtlasIconAndroid;
  case KSHIM_MENU_ROLE_INTERNAL: case KSHIM_MENU_ROLE_TF: return &AtlasIconLinux;
  case KSHIM_MENU_ROLE_ADVANCED: case KSHIM_MENU_ROLE_DEFAULT: return &AtlasIconGear;
  case KSHIM_MENU_ROLE_FASTBOOT: return &AtlasIconBolt;
  case KSHIM_MENU_ROLE_RECOVERY: return &AtlasIconRotate;
  case KSHIM_MENU_ROLE_EDL: return &AtlasIconDownload;
  case KSHIM_MENU_ROLE_SETTINGS: return &AtlasIconWrench;
  case KSHIM_MENU_ROLE_LANGUAGE: case KSHIM_MENU_ROLE_LANG_ZH: case KSHIM_MENU_ROLE_LANG_EN: return &AtlasIconGlobe;
  case KSHIM_MENU_ROLE_DEVICE_INFO: case KSHIM_MENU_ROLE_DEVICE: return &AtlasIconInfo;
  case KSHIM_MENU_ROLE_RESTART: return &AtlasIconRestart;
  case KSHIM_MENU_ROLE_OFF: return &AtlasIconPower;
  case KSHIM_MENU_ROLE_BACK: return &AtlasIconBack;
  default: return NULL;
  }
}

